1226	diff --git a/seed-a-backend.Tests/TestSupport/SqlServerTestDatabase.cs b/seed-a-backend.Tests/TestSupport/SqlServerTestDatabase.cs
1227	new file mode 100644
1228	index 0000000..d03c3e6
1229	--- /dev/null
1230	+++ b/seed-a-backend.Tests/TestSupport/SqlServerTestDatabase.cs
1231	@@ -0,0 +1,49 @@
1232	+using Microsoft.Data.SqlClient;
1233	+using Microsoft.EntityFrameworkCore;
1234	+using seed_a_backend.Api.Data;
1235	+
1236	+namespace seed_a_backend.Tests.TestSupport;
1237	+
1238	+/// <summary>
1239	+/// Testinfrastruktur-Entscheidung (siehe Story Dev Notes "Testinfrastruktur"): Tests laufen gegen eine
1240	+/// echte, über <c>ConnectionStrings__Default</c> erreichbare SQL-Server-Instanz, da der EF-Core-InMemory-Provider
1241	+/// das JSON-Spalten-Mapping von <c>Raum.Reihen</c>/<c>Raum.GangSpalten</c> (AD-1) nicht zuverlässig abbildet.
1242	+/// Jede Testklasse erhält eine eigene, per Discriminator benannte Datenbank, die vor jedem Test frisch migriert wird.
1243	+/// </summary>
1244	+internal static class SqlServerTestDatabase
1245	+{
1246	+    public static string BuildConnectionString(string discriminator)
1247	+    {
1248	+        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
1249	+            ?? throw new InvalidOperationException(
1250	+                "ConnectionStrings__Default ist nicht gesetzt. Die Backend-Tests benötigen eine erreichbare SQL-Server-Instanz.");
1251	+
1252	+        var builder = new SqlConnectionStringBuilder(baseConnectionString)
1253	+        {
1254	+            InitialCatalog = new SqlConnectionStringBuilder(baseConnectionString).InitialCatalog + "_" + discriminator
1255	+        };
1256	+        return builder.ConnectionString;
1257	+    }
1258	+
1259	+    public static async Task<AppDbContext> CreateFreshContextAsync(string discriminator)
1260	+    {
1261	+        var options = new DbContextOptionsBuilder<AppDbContext>()
1262	+            .UseSqlServer(BuildConnectionString(discriminator))
1263	+            .Options;
1264	+
1265	+        var db = new AppDbContext(options);
1266	+        await db.Database.EnsureDeletedAsync();
1267	+        await db.Database.MigrateAsync();
1268	+        return db;
1269	+    }
1270	+
1271	+    public static async Task DropAsync(string discriminator)
1272	+    {
1273	+        var options = new DbContextOptionsBuilder<AppDbContext>()
1274	+            .UseSqlServer(BuildConnectionString(discriminator))
1275	+            .Options;
1276	+
1277	+        await using var db = new AppDbContext(options);
1278	+        await db.Database.EnsureDeletedAsync();
1279	+    }
1280	+}
