1	using System.Text.Json;
2	using System.Text.Json.Serialization;
3	using Microsoft.EntityFrameworkCore;
4	using seed_a_backend.Api.Models;
5	
6	namespace seed_a_backend.Api.Data;
7	
8	public static class SeedLoader
9	{
10	    public static async Task SeedAsync(AppDbContext db, string anfangsdatenbestandPfad)
11	    {
12	        if (await db.Spielstaetten.AnyAsync())
13	        {
14	            return;
15	        }
16	
17	        var json = await File.ReadAllTextAsync(anfangsdatenbestandPfad);
18	        var bestand = JsonSerializer.Deserialize<AnfangsdatenbestandDto>(json, new JsonSerializerOptions
19	        {
20	            PropertyNameCaseInsensitive = true
21	        }) ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht gelesen werden: {anfangsdatenbestandPfad}");
22	
23	        var raeumeNachId = new Dictionary<string, Raum>();
24	
25	        foreach (var spielstaetteDto in bestand.Spielstaetten)
26	        {
27	            var spielstaette = new Spielstaette
28	            {
29	                Id = spielstaetteDto.Id,
30	                Name = spielstaetteDto.Name
31	            };
32	            db.Spielstaetten.Add(spielstaette);
33	
